create table public.studio_enquiries(id uuid primary key, guest_name text not null check(char_length(trim(guest_name)) between 1 and 120), contact text not null check(char_length(trim(contact)) between 5 and 30), email text check(char_length(email)<=200), service text not null check(service in ('Photography','Pre-wedding Photography','Content Studio','Video & Cinematography','Audio Recording & Production','Branding & Creative Production','BDS Academy')), package_label text not null check(char_length(package_label) between 1 and 300), preferred_date date not null, preferred_time time not null, duration_label text not null check(char_length(duration_label) between 1 and 60), details text not null check(char_length(trim(details)) between 1 and 2000), created_at timestamptz not null default now()); alter table public.studio_enquiries enable row level security; revoke all on public.studio_enquiries from public,anon,authenticated; grant insert(id,guest_name,contact,email,service,package_label,preferred_date,preferred_time,duration_label,details) on public.studio_enquiries to anon,authenticated; grant select on public.studio_enquiries to authenticated; create policy enquiry_submit on public.studio_enquiries for insert to anon,authenticated with check(preferred_date >= (now() at time zone 'Africa/Lagos')::date and preferred_date <= (now() at time zone 'Africa/Lagos')::date+730); create policy enquiry_admin_read on public.studio_enquiries for select to authenticated using(exists(select 1 from public.studio_admin_memberships where user_id=(select auth.uid())));
